// Generated assets for the edge contract PDF renderer. Kept under data/
// because the base64 payloads are exempt from the source line limit.

// Cairo (Arabic + Latin) subset, static weights 400/700, from the OFL Cairo
// variable font. Arabic presentation-form ranges are retained so shaping works.
export const CAIRO_REGULAR_BASE64 =
  "";

export const CAIRO_BOLD_BASE64 =
  "";

// Kanjo mark, 200x200 JPEG (8 KB) derived from the 1254px brand logo. JPEG is
// used because png-js spawns a Web Worker to inflate PNG pixels, which the edge
// runtime does not provide.
export const KANJO_LOGO_BASE64 =
  "";
